let financialScope='metals';
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(),now=()=>new Date().toISOString(),stamp=s=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'尚未获取';
const dateLabel=s=>s?String(s).slice(0,10):'来源未提供';
const frame=id=>FRAMES.find(f=>f.id===id),safeURL=s=>{try{let u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
const KEY='guanlan-workbench-v2',OLDKEY='guanlan-prototype-v1';
const fresh=()=>({schema:2,entries:[],watches:[],companies:[],draft:null,disabledFeeds:[],history:[],legacy:null,focusKeywords:''});
let state=fresh(),storageProblem=false;
try{let raw=localStorage.getItem(KEY);if(raw){const x=JSON.parse(raw);if(x.schema!==2||!Array.isArray(x.entries)||!Array.isArray(x.companies)||!Array.isArray(x.watches))throw Error();state={...fresh(),...x};}else{let old=localStorage.getItem(OLDKEY);if(old)state.legacy=JSON.parse(old);}}catch{storageProblem=true;}
let remote=typeof PUBLIC_SNAPSHOT==='undefined'?{sources:{},catalog:[],ai:{configured:false}}:PUBLIC_SNAPSHOT,online=false,route='home',selected='financial',subtab='framework',readerStep=1,busy=false,newsScope='node',newsQuery='',newsSource='',narrativeTab='library',financialPeriod='';
let draft=state.draft||{title:'',text:'',kind:'播客笔记',sourceURL:'',claim:'',question:'',counter:'',node:'policy',segment:1,stance:'待核查',keywords:'',watch:false,mode:'手动整理',demo:false};
const parts=()=>draft.text.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);
// The last successful write is the transaction boundary for every research mutation.
let committedState=JSON.stringify(state);
function save(){
 state.draft=draft;
 try{
  if(storageProblem)throw Error();
  const next=JSON.stringify(state);localStorage.setItem(KEY,next);committedState=next;
  $('#save-state').textContent='已保存到本浏览器';return true;
 }catch{
  state=JSON.parse(committedState);
  // Keep the current material draft available for export/retry, without claiming it is saved.
  state.draft=draft;
  if($('#dialog')?.open)closeDialog();
  render();$('#save-state').textContent='保存异常 · 本次研究修改已撤销';
  toast('未能保存，本次研究修改已撤销；当前材料草稿暂留内存，请导出备份后再操作');return false;
 }
}
function persist(){return save();}
function log(type,note){state.history.unshift({time:now(),type,note});}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4200);}
function go(area,node){if(node)selected=node;location.hash=area;route=area;if(area!=='reader')subtab='framework';render();window.scrollTo(0,0);}
function dialog(title,body,actions=''){let d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" aria-label="关闭">×</button></div><div class="dialog-body">${body}</div><div class="actions">${actions}</div>`;$('.close').onclick=()=>d.close();if(!d.open)d.showModal();bindLinks(d);}
function closeDialog(){$('#dialog').close();}
function action(label,name,extra='',style='button'){return `<button class="${style}" data-action="${name}" ${extra}>${label}</button>`;}
function empty(title,text,button=''){return `<div class="empty"><strong>${title}</strong><p>${text}</p>${button}</div>`;}
function heading(kicker,title,text,button=''){return `<div class="eyebrow">${kicker}</div><div class="title-row"><div><h1>${title}</h1><p class="subtitle">${text}</p></div>${button}</div>`;}
function selectNodes(value){return FRAMES.map(f=>`<option value="${f.id}" ${f.id===value?'selected':''}>${AREAS[f.area]} / ${f.name}</option>`).join('');}
function allNews(){
 const candidates=Object.values(remote.sources).flatMap(s=>s.kind==='feed'&&!state.disabledFeeds.includes(s.id)?(s.items||[]).map(i=>({...i,fetchStatus:s.status,fetchedAt:i.firstFetchedAt||s.fetchedAt})):[]).sort((a,b)=>(b.publishedAt||'').localeCompare(a.publishedAt||''));
 const grouped=new Map();
 for(const item of candidates){const key=item.dedupKey||item.id;if(grouped.has(key)){const prior=grouped.get(key);prior.alsoFrom=[...new Set([...(prior.alsoFrom||[]),item.source])];prior.nodes=[...new Set([...prior.nodes,...item.nodes])];prior.feedIds=[...new Set([...prior.feedIds,item.feedId])];}else grouped.set(key,{...item,id:key,feedIds:[item.feedId]});}
 return [...grouped.values()];
}
function matched(w){const terms=w.keywords.split(/[,，\n]/).map(x=>x.trim().toLowerCase()).filter(Boolean);return allNews().filter(i=>terms.some(t=>i.title.toLowerCase().includes(t)));}
function render(){$('#page').oninput=null;$('#page').onchange=null;if(!AREAS[route])route='home';$('#nav').innerHTML=NAV.map(([id,icon,name,sub])=>`<button class="nav-item ${route===id?'active':''}" data-route="${id}" ${route===id?'aria-current="page"':''}><span class="icon">${icon}</span><span><strong>${name}</strong><small>${sub}</small></span></button>`).join('');$('#crumb').textContent=`研究空间 / ${AREAS[route]}`;$('#connection').textContent=online?'本地数据服务已连接':'离线快照 · 可整理材料';$('#page').innerHTML=route==='home'?home():route==='inbox'?researchInbox():route==='reader'?reader():route==='settings'?settings():route==='narrative'?narratives():route==='companies'?companies():research();if(!online&&remote.snapshot)$('#page').insertAdjacentHTML('afterbegin',`<div class="notice warn snapshot-note">离线数据预览 · 采集检查 ${stamp(remote.checkedAt)}。每源最多展示 12 条新闻、40 个观察值或 8 期财报；不是实时数据。启动本地服务后可刷新和查看完整缓存。</div>`);bindLinks(document);bindPage();if($('#financial-period'))$('#financial-period').onchange=e=>{financialPeriod=e.target.value;render();};if(storageProblem)$('#save-state').textContent='读取异常 · 原数据未覆盖';}
function home(){const active=state.watches.filter(w=>w.active),due=active.reduce((a,w)=>a+matched(w).filter(i=>!w.seen?.includes(i.id)).length,0);return heading('RESEARCH WITH CONTEXT','让信息有来处，让研究有框架。','从宏观环境到贵金属，再到 A 股公司。每天沿着同一组问题，观察什么正在改变。')+`<section class="hero"><div><div class="eyebrow">YOUR RESEARCH ROUTE</div><h2>先知道要看什么，<br>再判断新信息改变了什么。</h2><p>框架是起点。数据与新闻提供证据，材料研读把新的启发放回已有问题。</p><div class="actions">${action('走一遍材料归档 →','demo','','primary')}${action('先看宏观框架','goto','data-area="macro"')}</div></div><div class="hero-map">${[['macro','01 宏观环境','增长 · 通胀 · 政策 · 金融'],['metals','02 贵金属产业','黄金 · 白银 · 产业链'],['companies','03 A 股公司','经营 · 估值 · 技术'],['narrative','↗ 叙事观察','假设 · 里程碑 · 反证']].map(([a,n,d])=>`<button data-route="${a}">${n}<small>${d}</small></button>`).join('')}</div></section><div class="section-head"><h2>我的研究进度</h2><span class="muted">框架内的证据与持续观察</span></div><div class="stat-row"><div class="card"><div class="count">${state.entries.length.toString().padStart(2,'0')}</div><small>已归档的材料观点</small></div><div class="card"><div class="count">${active.length.toString().padStart(2,'0')}</div><small>正在观察的主题</small></div><div class="card"><div class="count">${due.toString().padStart(2,'0')}</div><small>主题命中条次 · 可能重复</small></div></div><div class="grid"><div><section class="card"><div class="card-head"><h2>今天，从这里开始</h2><span class="pill">两条工作流</span></div><div class="journey-item"><span class="number">01</span><div><h3>日常查看：沿框架看变化</h3><p>选择一个问题，查看数据的观察日期与新闻来源。</p></div>${action('打开宏观 →','goto','data-area="macro"','ghost')}</div><div class="journey-item"><span class="number">02</span><div><h3>主动研究：拆解一份材料</h3><p>保留原文，判断它支持、挑战还是补充哪个问题。</p></div>${action('导入材料 →','goto','data-area="reader"','ghost')}</div><div class="journey-item"><span class="number">03</span><div><h3>持续观察：等待新的证据</h3><p>确认追踪主题后，在已接入的新闻中匹配关键词。</p></div>${action('查看主题 →','goto','data-area="narrative"','ghost')}</div></section><section class="card"><h2>最近归档</h2>${entryList(state.entries.slice(-3).reverse())}</section></div><aside><section class="card"><div class="card-head"><h3>数据连接</h3><span class="pill ${online?'':'warm'}">${online?'本地服务在线':'离线模式'}</span></div><p>${online?`公开源最近检查：${stamp(remote.checkedAt)}`:'通过「启动原型.command」开启数据与指标服务；离线也能导入、归档和导出材料。'}</p><p>实时行情与 A 股财报尚未接入。已取到的公开数据会显示真实时间，不用示例值补空。</p>${action('查看连接状态 →','goto','data-area="settings"','ghost')}</section><section class="card"><div class="eyebrow">FIRST FOCUS</div><h3>只把一个研究范围做扎实</h3><p>A 股贵金属相关公司。先分清产业链角色，再解释行业变化如何进入利润与现金流。</p>${action('看贵金属产业链 →','chain','','ghost')}</section></aside></div>`;}
function tabs(items){return `<div class="tabs" role="tablist">${items.map(([id,label])=>`<button role="tab" aria-selected="${subtab===id}" class="${subtab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div>`;}
function research(){const isMacro=route==='macro';if(!FRAMES.some(f=>f.area===route&&f.id===selected))selected=isMacro?'financial':'gold';const f=frame(selected);return heading(isMacro?'MACRO ENVIRONMENT':'PRECIOUS METALS',isMacro?'宏观环境':'贵金属产业',isMacro?'用增长、通胀、政策与货币金融四个维度，识别资产所处的环境。':'先分清黄金与白银的主导属性，再沿产业链追踪变化。',action('＋ 补充一份材料','import-node',`data-node="${f.id}"`))+tabs([['framework','研究框架'],...(isMacro?[]:[['chain','产业链地图']]),['data','数据面板'],['news','相关信息'],['evidence','我的证据']])+`<div class="framework-grid"><aside class="tree"><div class="tree-root">${isMacro?'宏观研究 / 四个维度':'贵金属 / 两种研究对象'}</div>${FRAMES.filter(x=>x.area===route).map(x=>`<button class="${x.id===selected?'active':''}" data-node="${x.id}"><strong>${x.name}</strong><small>${x.sub}</small></button>`).join('')}</aside><div>${subtab==='framework'?nodeCard(f):subtab==='chain'?chain(f):subtab==='data'?dataPanel(f):subtab==='news'?newsPanel(f):`<section class="card"><h2>${f.name} · 我的证据</h2>${entryList(state.entries.filter(e=>e.node===f.id).reverse())}</section>`}</div></div>`;}
function nodeCard(f){return `<section class="card node-detail"><div class="card-head"><span class="eyebrow">${f.name} / 核心问题</span><span class="pill">方法底座 v1</span></div><h2>${f.question}</h2><p>${f.desc}</p><div class="flow">${f.path.map((x,i)=>`${i?'<i>→</i>':''}<span>${x}</span>`).join('')}</div><div class="split"><div><h3>先回答这三个问题</h3><ul class="list">${f.checks.map(q=>`<li>◦ ${q}</li>`).join('')}</ul></div><div><h3>对应观察项</h3><ul class="list">${f.metrics.map(q=>`<li>${q}</li>`).join('')}</ul><div class="actions">${action('查看数据 →','node-data',`data-node="${f.id}"`,'ghost')}${action('查看相关信息 →','node-news',`data-node="${f.id}"`,'ghost')}</div></div></div><div class="notice"><b>什么情况需要重新判断？</b><br>${f.counter}</div><div class="basis">方法来源：${f.basis}。用于组织研究，不把历史案例与相关关系当作固定预测规则。</div></section><section class="card"><div class="card-head"><h3>落在这个问题下的材料</h3>${action('补充证据 ＋','import-node',`data-node="${f.id}"`,'ghost')}</div>${entryList(state.entries.filter(e=>e.node===f.id).slice(-3).reverse())}</section>`;}
function spark(points){if(!points?.length)return '';const values=points.map(x=>Number(x.value)),lo=Math.min(...values),hi=Math.max(...values),r=hi-lo||1;let coords=values.map((v,i)=>`${(i/(values.length-1||1)*300).toFixed(2)},${(48-(v-lo)/r*41).toFixed(2)}`).join(' ');return `<svg viewBox="0 0 300 55" preserveAspectRatio="none" role="img" aria-label="最近 ${values.length} 个有效观察值的走势，纵轴自动缩放"><line x1="0" y1="52" x2="300" y2="52" stroke="#e3e9d9"/><polyline points="${coords}" fill="none" stroke="#879b67" stroke-width="1.7" vector-effect="non-scaling-stroke"/></svg>`;}
function seriesCard(s){let p=s.points||[],v=p.at(-1),delta=p.length>1?v.value-p.at(-2).value:null;return `<article class="metric"><div class="card-head"><span class="metric-label">${esc(s.name)}</span><span class="pill ${s.status==='ok'?'':'warm'}">${s.status==='ok'?'已获取':s.status==='stale'?'旧缓存':'未获取'}</span></div><div class="metric-value">${v?Number(v.value).toFixed(2):'—'} <small>${esc(s.unit)}</small></div>${spark(p)}<div class="metric-meta">${p.length?`区间 ${p[0].date} — ${v.date} · 纵轴自动缩放<br>`:''}${delta===null?'无可比前值':`较前一有效观察值 ${delta>=0?'+':''}${delta.toFixed(2)} ${esc(s.deltaUnit||(s.unit==='%'?'个百分点':'点'))}`}<br>观察${v?.date?.length===7?'月份':'日期'} ${v?.date||'—'} · ${esc(s.frequency)}<br>抓取时间 ${stamp(s.fetchedAt)}<br>发布时间：接口未提供${s.status==='stale'?'<br><b>最近抓取失败，保留上次数据</b>':''}<br><a href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.provider||'FRED')} ↗</a></div>${v&&/^\d{4}-\d{2}$/.test(v.date)&&new Date()-new Date(v.date+'-01')>100*86400000?'<div class="notice warn">月度数据覆盖较旧，抓取成功不代表已更新到最新月份。</div>':''}${s.note?`<p class="metric-note">${esc(s.note)}</p>`:''}</article>`;}
function annualPanel(node){const a=ANNUAL_METALS[node];if(!a)return '';return `<section class="card annual-panel"><div class="card-head"><h2>${esc(a.title)}</h2><span class="pill warm">年度资料 · 人工核验摘录</span></div><p class="muted">观察期 ${esc(a.period)} · 报告发布 ${a.published} · 摘录核查 ${a.reviewed}</p><div class="table-wrap"><table><thead><tr><th>指标</th><th>${esc(a.unit)}</th><th>如何理解</th></tr></thead><tbody>${a.rows.map(([label,value,note])=>`<tr><td>${esc(label)}</td><td>${value.toLocaleString('zh-CN',{minimumFractionDigits:1})}</td><td>${esc(note)}</td></tr>`).join('')}</tbody></table></div><p><strong>下一步研究：</strong>${esc(a.question)}</p><div class="notice">${esc(a.boundary)} 点击“检查更新”只刷新已接接口，不会替换这份年度摘录。</div><p>来源：${esc(a.source)} · <a href="${safeURL(a.url)}" target="_blank" rel="noopener noreferrer">阅读报告与口径 ↗</a></p>${action('带入材料研读 →','annual-import',`data-node="${node}"`,'ghost')}</section>`;}
function annualImport(node){const a=ANNUAL_METALS[node];if(!a)return;if(draft.text.trim()&&!confirm('当前有未归档草稿。将年度摘录放入编辑器会替换草稿，是否继续？'))return;draft={title:a.title,text:`来源：${a.source}\n观察期：${a.period}；报告发布：${a.published}\n\n`+a.rows.map(([n,v,note])=>`${n}：${v} ${a.unit}。${note}。`).join('\n\n')+`\n\n口径边界：${a.boundary}`,kind:'研究报告摘录',sourceURL:a.url,claim:'',question:a.question,counter:'',node,segment:1,stance:'待核查',keywords:node==='gold'?'黄金,ETF,央行':'白银,光伏,耗银',watch:false,mode:'手动整理',demo:false};readerStep=1;if(!save())return;go('reader');}
function dataPanel(f){let series=(remote.catalog.length?remote.catalog:[{id:'DFII10',name:'美国 10 年期实际收益率',unit:'%',frequency:'日度',nodes:['financial','gold'],url:'https://fred.stlouisfed.org/series/DFII10',kind:'series'}]).filter(s=>s.kind==='series'&&s.nodes.includes(f.id));return `<div class="card-head"><div><h2>${f.name} · 数据面板</h2><p class="muted">数据回答具体问题；每日检查不代表所有指标每天发布。</p></div>${action(busy?'检查中…':'检查更新','refresh',busy?'disabled':'','button small')}</div><div class="metrics" style="grid-template-columns:repeat(${Math.min(series.length||1,2)},minmax(0,1fr))">${series.map(s=>seriesCard(remote.sources[s.id]||s)).join('')}</div>${annualPanel(f.id)}${f.id==='policy'?`<section class="card"><h3>政策观察以发布和执行节点为起点</h3><p>先阅读带日期的政策信息，再区分表态、提案与实际执行。</p>${newsItems(allNews().filter(i=>i.nodes.includes('policy')).slice(0,4))}</section>`:''}<section class="card"><h3>框架观察项 · 数据覆盖情况</h3><ul class="list">${f.metrics.map((x,i)=>`<li>${esc(x)} <span class="pill gray">${metricCoverage(f.id,i)}</span></li>`).join('')}</ul><div class="notice">已接入 PMI、CPI、PPI、M2、社融增量、LPR、金银合约价格与 FRED 序列。年度供需摘要见贵金属面板；AISC、光伏单位耗银、全市场 ETF 持仓等自动数据仍待接入，价格不能替代这些证据。</div>${action('查看数据源与接入范围 →','goto','data-area="settings"','ghost')}</section>`;}
function newsItems(items){return items.length?items.map(i=>`<article class="feed"><a class="feed-title" href="${safeURL(i.url)}" target="_blank" rel="noopener noreferrer">${esc(i.title)} ↗</a><div class="feed-meta">${esc(i.source)}${i.publisher&&i.publisher!==i.source?` · 发布方 ${esc(i.publisher)}`:''} · 发布 ${i.publishedAt?stamp(i.publishedAt):'来源未提供'} · 首次抓取 ${dateLabel(i.fetchedAt)} ${i.fetchStatus==='stale'?'· 旧缓存':''}</div>${i.alsoFrom?.length?`<div class="feed-meta">同题来源：${esc(i.alsoFrom.join('、'))}（已折叠，不作为独立证据计数）</div>`:''}<div class="feed-tags">${i.nodes.slice(0,5).map(n=>`<span class="pill">${esc(frame(n)?.name||n)}</span>`).join(' ')}</div><details class="feed-reason"><summary>为什么出现在这里${i.linkKind==='collection'?' · 链接为来源列表':''}</summary><p>${esc(i.classification||'订阅源主题映射')}。这是相关性线索，不代表支持研究结论。${i.linkKind==='collection'?'上游未提供单篇链接，请到来源列表按标题和发布时间核对。':''}</p></details>${action('记录阅读后的证据 →','news-import',`data-news="${esc(i.id)}"`,'ghost')}</article>`).join(''):empty('这个筛选下暂时没有匹配信息','可以切换“本层全部”或“全部信息源”继续查找；无结果不等于外部没有变化。');}
function newsPanel(f){let all=allNews(),area=frame(f.id)?.area||route;let items=all.filter(i=>newsScope==='all'||(newsScope==='layer'?i.nodes.some(n=>frame(n)?.area===area):i.nodes.includes(f.id)));if(newsSource)items=items.filter(i=>i.feedIds.includes(newsSource));if(newsQuery)items=items.filter(i=>i.title.toLowerCase().includes(newsQuery.toLowerCase()));return `<section class="card"><div class="card-head"><h2>${f.name} · 相关信息</h2>${action(busy?'检查中…':'检查更新','refresh',busy?'disabled':'','button small')}</div><p class="muted">官方发布与中文财经快讯分源采集，按研究节点分类。同日同标题会折叠；近似标题暂不自动视为同一事件。</p><div class="news-filters"><label>查看范围<select id="news-scope"><option value="node" ${newsScope==='node'?'selected':''}>当前问题</option><option value="layer" ${newsScope==='layer'?'selected':''}>本层全部</option><option value="all" ${newsScope==='all'?'selected':''}>全部信息源</option></select></label><label>来源<select id="news-source"><option value="">所有已启用来源</option>${remote.catalog.filter(s=>s.kind==='feed'&&!state.disabledFeeds.includes(s.id)).map(s=>`<option value="${s.id}" ${s.id===newsSource?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>标题关键词<input id="news-query" maxlength="80" value="${esc(newsQuery)}" placeholder="如：黄金、政策、光伏"></label>${action('筛选','filter-news','','button')}</div><div class="feed-meta">匹配 ${items.length} 条 · 展示最近 ${Math.min(items.length,80)} 条 · 时间由上游提供，抓取成功不等于内容为今天发布</div>${newsItems(items.slice(0,80))}</section>`;}
function chain(f){const silver=f.id==='silver';const cols=silver?[['01 上游 · 矿产与再生',[['伴生银','铜、铅锌、金矿的生产与投资决定部分供给弹性。'],['独立银矿与回收','分别核对矿山供给和再生银口径。']]],['02 中游 · 冶炼与精炼',[['冶炼回收','从矿石及副产品中回收白银。'],['标准化银锭','精炼、库存、交割连接不同市场。']]],['03 下游 · 使用与持有',[['工业与光伏','装机增长需结合单位耗银、替代路线。'],['首饰与投资','实物消费与投资持有分别观察。']]]]:[['01 上游 · 矿产与回收',[['矿山生产','储量、品位、产量、AISC 与资本开支。'],['回收金','地上存量回流，不等于新增矿产。']]],['02 中游 · 冶炼与精炼',[['冶炼与精炼','核对原料来源、加工费和成本传导。'],['标准化与流通','金锭、交易与交割连接不同需求方。']]],['03 下游 · 消费与持有',[['首饰与工业','终端消费及加工需求。'],['投资与储备','金条、ETF 与央行储备等持有形式。']]]];return `<section class="card"><div class="card-head"><h2>${f.name} · 产业链地图</h2><span class="pill">角色结构</span></div><p>先看各环节如何赚钱，再找公司。下面是行业结构，不代表已确认的企业供应关系。</p><div class="chain">${cols.map(([h,items])=>`<div class="chain-col"><h3>${h}</h3>${items.map(([n,d])=>`<div class="chain-node"><strong>${n}</strong><p>${d}</p>${action('按此角色添加公司 →','add-company',`data-role="${esc(n)}"`,'ghost')}</div>`).join('')}</div>`).join('')}</div><div class="notice"><b>另一个维度：定价与交易参与者</b><br>央行、ETF、投资机构、交易商和终端消费者的行为需要分别观察；它们不能被简单排列成生产上下游。</div>${action('回到驱动框架 →','node-framework',`data-node="${f.id}"`,'ghost')}</section>`;}
function entryList(entries){return entries.length?entries.map(e=>`<article class="entry"><div class="meta"><span class="pill">${esc(frame(e.node)?.name||'未归类')}</span><span class="pill warm">${esc(e.stance)}</span>${e.demo?'<span class="pill gray">教学示例</span>':''}<span class="pill gray">v${e.version}</span></div><h3>${esc(e.claim)}</h3><p>接下来验证：${esc(e.question)}</p><div class="feed-meta">${esc(e.title)} · §${e.segment} · ${stamp(e.created)} · ${esc(e.mode)}</div><div class="actions">${action('核对原文 ↗','source',`data-entry="${e.id}"`,'ghost')}${action('补充 / 修订','edit-entry',`data-entry="${e.id}"`,'ghost')}${action('查看历史','entry-history',`data-entry="${e.id}"`,'ghost')}${action('研究链路 →','research-detail',`data-entry="${e.id}"`,'ghost')}</div></article>`).join(''):empty('这里还没有你的证据','框架已经准备好。导入一份材料，将观点关联到这个问题。',action('去材料研读 →','import-node',`data-node="${selected}"`,'ghost'));}
function reader(){return heading('READ, CONNECT, VERIFY','材料研读','把一份播客笔记、文章或研究记录，转成框架中的一个可追踪问题。',`<div class="actions">${action('新建材料','new-source')}${action('载入教学示例','demo')}</div>`)+`<div class="steps" aria-label="材料归档流程">${['导入材料','拆解与归类','确认归档'].map((x,i)=>`<div class="step ${readerStep===i+1?'active':readerStep>i+1?'done':''}"><b>0${i+1}</b>${x}</div>`).join('')}</div>${readerStep===1?readerImport():readerStep===2?readerReview():readerConfirm()}`;}
function readerImport(){return `<div class="grid"><section class="card"><h2>01 / 留住完整的上下文</h2><p>先导入文字。按空行分段，之后每条观点都保留原文定位。</p><div class="form-row"><div><label for="source-title">材料标题</label><input id="source-title" maxlength="160" value="${esc(draft.title)}" placeholder="例如：贵金属需求变化的讨论"></div><div><label for="source-kind">材料类型</label><select id="source-kind">${['播客笔记','文章','研究记录','研究报告摘录','书籍笔记','教学示例'].map(k=>`<option ${draft.kind===k?'selected':''}>${k}</option>`).join('')}</select></div></div><label for="source-url">原始链接（可选）</label><input id="source-url" value="${esc(draft.sourceURL)}" placeholder="https://…"><label for="source-file">导入 TXT / Markdown（UTF-8，最多 200 KB）</label><input id="source-file" type="file" accept=".txt,.md,text/plain,text/markdown"><label for="source-text">材料正文（最多 50,000 字符）</label><textarea id="source-text" maxlength="50000" rows="12" placeholder="粘贴笔记正文；段落之间留空行。">${esc(draft.text)}</textarea><div id="reader-error" class="error" role="alert"></div><div class="actions">${action('下一步：拆解与归类 →','reader-next','','primary')}</div></section><aside><section class="card"><h3>这一步会发生什么</h3><p>正文首先保存在当前浏览器。下一步可以手动整理，也可以主动调用你配置的 AI。</p><p>平台不会把作者的推测自动升级为事实，也不会自行改写原有研究结论。</p><span class="pill ${remote.ai?.configured?'':'warm'}">${remote.ai?.configured?'AI 已配置 · 点击后调用':'AI 尚未配置 · 手动流程可用'}</span></section><section class="card"><h3>上手提示</h3><p>用右上角的教学示例，可以在不准备材料的情况下走完整个流程。示例不会自动保存为真实研究。</p></section></aside></div>`;}
function readerReview(){let seg=parts()[draft.segment-1]||'';return `<div class="grid"><section class="card"><div class="card-head"><div><h2>02 / 这条信息放在哪里？</h2><span class="pill">${esc(draft.mode)}</span></div>${action(busy?'分析中…':'AI 辅助拆解','ai',!remote.ai?.configured||busy?'disabled':'')}</div><p class="muted">AI 调用将发送当前材料正文和框架摘要给 ${esc(remote.ai?.host||'你配置的服务商')}；不会发送其他研究记录。结果仍需逐条核对。</p>${draft.suggestions?.length?`<label for="ai-pick">本次 AI 提出的观点（逐条归档）</label><select id="ai-pick">${draft.suggestions.map((s,i)=>`<option value="${i}" ${draft.aiIndex===i?'selected':''}>${i+1}. ${esc(s.claim.slice(0,85))}</option>`).join('')}</select>`:''}<label for="source-segment">依据所在段落</label><select id="source-segment">${parts().map((p,i)=>`<option value="${i+1}" ${draft.segment===i+1?'selected':''}>§${i+1} ${esc(p.slice(0,55))}</option>`).join('')}</select><div class="source-paragraph">${esc(seg)}</div><label for="claim">你要保留的一条观点</label><textarea id="claim" maxlength="2000" placeholder="区分：作者观点、已披露事实与自己的推论。">${esc(draft.claim)}</textarea><div class="form-row"><div><label for="target-node">归入哪个框架问题</label><select id="target-node">${selectNodes(draft.node)}</select></div><div><label for="stance">对当前研究的作用</label><select id="stance">${['待核查','补充背景','支持假设','挑战假设','提出新问题'].map(x=>`<option ${draft.stance===x?'selected':''}>${x}</option>`).join('')}</select></div></div><label for="question">下一步要验证什么</label><textarea id="question" maxlength="1200">${esc(draft.question)}</textarea><label for="counter">出现什么情况，需要重新判断</label><textarea id="counter" maxlength="1200">${esc(draft.counter)}</textarea><div id="reader-error" class="error" role="alert"></div><div class="actions">${action('上一步','reader-back')}${action('下一步：确认归档 →','reader-check','','primary')}</div></section><aside><section class="card"><h3>归类建议如何产生</h3><p>未调用 AI 时，只根据关键词给出候选位置。你可以修改框架节点，原文不匹配时必须自行判断。</p><h3>一个材料可以有多个落点</h3><p>每次归档一条观点；归档后可以继续使用同一材料。这样每条证据都有自己的问题、来源和观察条件。</p></section><section class="card"><h3>已有框架不会被覆盖</h3><p>这里新增证据与观察主题。框架底座和已保存判断会保留；修改判断需要单独查看前后版本并确认。</p></section></aside></div>`;}
function readerConfirm(){const f=frame(draft.node);return `<div class="grid"><section class="card"><h2>03 / 确认这条研究记录</h2><div class="notice">将放入：<b>${AREAS[f.area]} → ${f.name} → 我的证据</b></div><h3>${esc(draft.claim)}</h3><p>作用：${esc(draft.stance)} · 来源：${esc(draft.title)} §${draft.segment}</p><div class="source-paragraph">${esc(parts()[draft.segment-1])}</div><h3>下一步验证</h3><p>${esc(draft.question)}</p><h3>重新判断的条件</h3><p>${esc(draft.counter)}</p><label><input type="checkbox" id="track-topic" ${draft.watch?'checked':''}>同时建立持续观察主题</label><label for="keywords">新闻匹配关键词（逗号分隔，中英文可并列）</label><input id="keywords" maxlength="250" value="${esc(draft.keywords)}" placeholder="例如：关税,tariff,policy"><p class="muted">仅匹配当前已接入新闻的标题；不是全网搜索，也不代表已验证观点。</p><div id="reader-error" class="error" role="alert"></div><div class="actions">${action('返回修改','reader-back')}${action('确认归档 →','reader-save','','primary')}</div></section><aside><section class="card"><h3>确认之后</h3><ul class="list"><li>原文与段落号留在证据卡中</li><li>记录出现在相应框架节点下</li><li>如勾选追踪，主题进入「叙事观察」</li><li>以后出现反证，可以修订并保留旧版本</li></ul></section></aside></div>`;}
function watchCard(x){return `<section class="card watch-card"><div><div class="meta"><span class="pill">${esc(frame(x.node)?.name)}</span> <span class="pill ${x.active?'':'gray'}">${x.active?'观察中':'已暂停'}</span>${x.templateId?' <span class="pill">从方法模板建立</span>':''}${x.demo?' <span class="pill warm">教学示例</span>':''}</div><h3>${esc(x.title)}</h3><p>验证问题：${esc(x.question)}</p><p>反证条件：${esc(x.counter)}</p>${x.baseline?`<p>预期基准：${esc(x.baseline)}</p>`:''}${x.milestones?.length?`<div class="milestone-list">${x.milestones.map((m,i)=>`<button data-action="milestone" data-watch="${x.id}" data-index="${i}"><span>${esc(m.title)}${m.dueDate?`<small>复核日 ${esc(m.dueDate)}</small>`:''}</span><span class="pill ${m.status==='出现反证'?'warm':'gray'}">${esc(m.status)}</span></button>`).join('')}</div>`:''}<div class="feed-meta">标题关键词：${esc(x.keywords)}</div><div class="actions">${action('看匹配信息','watch-news',`data-watch="${x.id}"`,'ghost')}${action('回到框架 →','open-node',`data-node="${x.node}"`,'ghost')}${action(x.active?'暂停观察':'恢复观察','toggle-watch',`data-watch="${x.id}"`,'ghost')}${action('编辑主题','edit-watch',`data-watch="${x.id}"`,'ghost')}${action('＋ 自定义里程碑','new-milestone',`data-watch="${x.id}"`,'ghost')}${milestoneDueLabel(x)}</div></div><div><span class="count">${x.active?matched(x).filter(i=>!x.seen?.includes(i.id)).length:'—'}</span><small class="muted"> 条未读命中</small></div></section>`;}
function narratives(){return heading('NARRATIVE OBSERVATORY','叙事观察','先拆清故事成立的条件，再用证据决定如何修订。方法库帮助你开始，个人观察保存你的判断。',action('＋ 新建观察主题','new-watch'))+`<div class="tabs" role="tablist"><button data-action="narrative-tab" data-value="library" class="${narrativeTab==='library'?'active':''}" role="tab" aria-selected="${narrativeTab==='library'}">方法与研究起点</button><button data-action="narrative-tab" data-value="watches" class="${narrativeTab==='watches'?'active':''}" role="tab" aria-selected="${narrativeTab==='watches'}">我的观察 · ${state.watches.length}</button></div>${narrativeTab==='library'?narrativeLibrary():`<div class="notice">新闻命中只是提醒。里程碑状态需要你填写依据后更新；不会自动生成概率或覆盖原有判断。</div>${state.watches.length?state.watches.map(watchCard).join(''):empty('尚未建立个人观察','先从方法库选择一个问题，核对假设后建立自己的观察。',action('选择一个研究起点 →','narrative-tab','data-value="library"','primary'))}`}`;}
function narrativeLibrary(){return `<section class="narrative-intro"><div><div class="eyebrow">从阅读稿提炼的方法底座</div><h2>一个好故事，还需要一条能被检验的路径。</h2><p>谁的预期 → 哪些条件 → 看什么证据 → 什么情况要改。以下模板尚未加入你的观察清单，也不是当前市场结论。</p></div><div class="flow"><span>预期基准</span><i>→</i><span>条件分支</span><i>→</i><span>证据修订</span></div></section><div class="template-grid">${NARRATIVE_TEMPLATES.map(t=>`<section class="card template-card"><div class="card-head"><span class="eyebrow">${t.label}</span><span class="pill">${t.origin}</span></div><h2>${t.title}</h2><p>${t.claim}</p><div class="template-steps">${t.milestones.map((m,i)=>`<div><span class="number">0${i+1}</span><span>${m}</span></div>`).join('')}</div><div class="actions">${action('查看路径与来源','template-detail',`data-template="${t.id}"`)}${action('用它建立观察 →','use-template',`data-template="${t.id}"`,'primary')}</div></section>`).join('')}</div><div class="section-head"><h2>历史案例怎样帮助研究</h2><span class="pill warm">阅读稿转译 · 原书细节待核</span></div><div class="split">${NARRATIVE_CASES.map(c=>`<section class="card"><h3>${c.title}</h3><p>${c.lesson}</p><ul class="list">${c.steps.map(x=>`<li>${x}</li>`).join('')}</ul><details><summary>来源与使用边界</summary><p>${c.source}</p><p>${c.limit}</p></details></section>`).join('')}</div><div class="notice">方法来自你提供的 NotebookLM 阅读与追问记录，不代表已直接核验原书。白银与黄金模板是本项目的方法迁移；不复制未核实的概率、归因比例或交易结论。</div>`;}
function companies(){if(!['business','valuation','technical'].includes(selected))selected='business';return heading('A-SHARE COMPANY RESEARCH','A 股公司','从材料与产业链寻找研究对象。自动财务覆盖五个样本，可按我的研究公司筛选；其他代码明确显示数据缺口。',action('＋ 添加研究公司','add-company'))+tabs([['framework','研究框架'],['list','公司与业务'],['financials','财务面板'],['compare','横向比较'],['news','相关信息'],['evidence','我的证据']])+(subtab==='framework'?`<div class="framework-grid"><aside class="tree"><div class="tree-root">公司研究 / 三个视角</div>${FRAMES.filter(x=>x.area==='companies').map(f=>`<button data-node="${f.id}" class="${selected===f.id?'active':''}"><strong>${f.name}</strong><small>${f.sub}</small></button>`).join('')}</aside><div>${nodeCard(frame(selected))}</div></div>`:subtab==='list'?`<section class="card"><h2>我的研究公司</h2>${state.companies.length?state.companies.map(c=>`<div class="company-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.code)} · ${esc(c.role)} · ${esc(c.reason)}</small></div><div class="actions">${companyOriginLinks(c)}${action('查看财务','company-financial',`data-company="${c.id}"`,'button small')}${action('记录估值','company-values',`data-company="${c.id}"`,'button small')}${action('获取历史价格','company-live-prices',`data-company="${c.id}"`,'button small')}${action('导入价格','company-prices',`data-company="${c.id}"`,'button small')}</div></div>`).join(''):empty('先从产业链角色选择研究对象','请自行添加公司与选取理由；当前未连接证券主数据，名称和代码不会被自动核验。',action('添加第一家公司','add-company','','primary'))}</section>`:subtab==='financials'?financialPanel():subtab==='compare'?compareCompanies():subtab==='news'?`<div class="notice">目前包含山东黄金、盛达资源的公司新闻检索样本；不是你的自选股清单，也不保证是完整公告。原始公告仍需到交易所或公司核对。</div>${newsPanel(frame('business'))}`:`<section class="card"><h2>公司研究 · 我的证据</h2>${entryList(state.entries.filter(e=>frame(e.node)?.area==='companies').reverse())}</section>`);}
function financialPanel(){
 const candidates=remote.catalog.filter(x=>x.kind==='financial'), myCodes=new Set(state.companies.map(c=>c.code)), missing=state.companies.filter(c=>!candidates.some(s=>s.symbol.split('.')[0]===c.code));
 const sources=candidates.filter(s=>financialScope==='all'||(financialScope==='mine'?myCodes.has(s.symbol.split('.')[0]):['600547','000603'].includes(s.symbol.split('.')[0]))).map(x=>remote.sources[x.id]||x),periods=[...new Set(sources.flatMap(s=>(s.reports||[]).map(r=>r.period)))].sort().reverse();
 if(!periods.includes(financialPeriod))financialPeriod=periods.find(p=>sources.every(s=>s.reports?.some(r=>r.period===p)))||periods[0]||'';
 const rows=sources.map(s=>({s,r:s.reports?.find(r=>r.period===financialPeriod)}));
 const metrics=[['revenue','营业总收入','亿元',1e8],['profit','归母净利润','亿元',1e8],['coreProfit','扣非归母净利润','亿元',1e8],['grossMargin','毛利率','%',1],['roe','加权 ROE','%',1],['debtRatio','资产负债率','%',1],['cashPerShare','每股经营现金流','元/股',1]];
 return `<section class="card"><div class="card-head"><div><h2>公开财务 · 同期观察</h2><p>先看收入、利润、回款与负债，再回到公司的业务解释。</p></div>${action(busy?'检查中…':'检查更新','refresh',busy?'disabled':'','button small')}</div><div class="notice">公开财务覆盖五家公司：两家贵金属样本与三家汽车/电池案例公司。列表按证券代码关联；不把名称输入视为身份核验。同报告期不等于业务可比，不能按每股现金流绝对大小排名。</div><label for="financial-scope">比较对象</label><select id="financial-scope"><option value="metals" ${financialScope==='metals'?'selected':''}>贵金属样本</option><option value="mine" ${financialScope==='mine'?'selected':''}>我的研究公司（已支持的代码）</option><option value="all" ${financialScope==='all'?'selected':''}>全部五家公开样本</option></select>${financialScope==='mine'&&missing.length?`<div class="notice warn">尚未支持：${missing.map(c=>esc(c.name)+' · '+esc(c.code)).join('、')}。不使用其他公司的数据代替。</div>`:''}${!sources.length?'<p>当前范围没有已支持的公司；请添加研究公司或切换比较范围。</p>':''}<label for="financial-period">共同查看的报告期末</label><select id="financial-period">${periods.map(p=>`<option ${p===financialPeriod?'selected':''}>${p}</option>`).join('')}</select><p class="muted">营收、利润和每股经营现金流为年初至报告期末累计；资产负债率为期末值；ROE 未年化。金额仅 CNY 按亿元展示。</p>${periods.length?`<div class="table-wrap"><table><thead><tr><th>指标 / 单位</th>${rows.map(({s,r})=>`<th>${esc(s.company)}<small>${esc(s.symbol)} · ${esc(r?.label||'本期缺失')}</small></th>`).join('')}</tr></thead><tbody>${metrics.map(([key,label,unit,div])=>`<tr><td>${label}<small>${unit}</small></td>${rows.map(({r})=>{let value=r?.values[key];return `<td>${Number.isFinite(value)&&r.currency==='CNY'?(value/div).toFixed(2):'—'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`:empty('尚无可用财务报告','启动本地服务检查更新；失败原因可在数据与设置查看。')}<div class="grid">${rows.map(({s,r})=>`<article class="entry"><h3>${esc(s.company)}</h3><span class="pill ${s.status==='ok'?'':'warm'}">${s.status==='ok'?'已获取':s.status==='stale'?'抓取失败 · 旧缓存':'未获取'}</span><p>报告期末 ${esc(r?.period||'本期缺失')}<br>接口记录的披露日期 ${esc(r?.publishedAt||'未提供')}<br>币种 ${esc(r?.currency||'未提供')}<br>成功抓取 ${stamp(s.fetchedAt)}</p><a href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">查看来源财务报表 ↗</a></article>`).join('')}</div><div class="notice">这里没有取得产量、AISC、资本开支或完整现金流量表；每股经营现金流不能替代经营现金流总额。接口数据仍应与公司披露核对。</div>${action('带着问题去读财报 →','import-node','data-node="business"','ghost')}</section>`;
}
function compareCompanies(){const cs=state.companies;return `<div class="notice">估值来自你录入的同口径快照，技术指标由 TA-Lib 对导入价格计算。支持五个样本的历史日线，不含当天未收盘数据；不生成综合评分或买卖信号。</div>${!cs.length?empty('先添加研究对象','添加公司后，可录入估值快照或上传价格 CSV 进行比较。',action('添加公司','add-company','','primary')):`<h2>估值快照</h2><div class="table-wrap"><table><thead><tr><th>公司 / 业务角色</th><th>PE(TTM)</th><th>PB</th><th>估值日期 / 报告期</th><th>来源与口径</th><th>操作</th></tr></thead><tbody>${cs.map(c=>`<tr><td>${esc(c.name)}<small>${esc(c.code)} · ${esc(c.role)}</small></td><td>${c.valuation?.pe??'—'}</td><td>${c.valuation?.pb??'—'}</td><td>${esc(c.valuation?.date||'未录入')}<small>${esc(c.valuation?.period||'')}</small></td><td>${esc(c.valuation?.source||'—')}<small>${esc(c.valuation?.currency||'')}</small></td><td>${action('录入','company-values',`data-company="${c.id}"`,'button small')}</td></tr>`).join('')}</tbody></table></div><p class="muted">${comparable(cs,'valuation')?'已录入快照日期、报告期与币种一致；仍需核对业务与会计口径。':'快照不完整或日期 / 报告期 / 币种不同，暂不适合直接排名。'} PE ≤ 0 不作为“更便宜”的证据。</p><div class="section-head"><h2>价格与技术指标</h2><span class="pill">TA-Lib · MA20 / RSI14 / MACD</span></div><div class="table-wrap"><table><thead><tr><th>公司</th><th>收盘价 / MA20</th><th>RSI14</th><th>MACD / Signal / Hist</th><th>截止日 / 复权</th><th>操作</th></tr></thead><tbody>${cs.map(c=>{let t=c.technical;const num=n=>Number.isFinite(n)?n.toFixed(2):'—';return `<tr><td>${esc(c.name)}<small>${t?`${t.rows} 条价格`:'无价格数据'}</small>${t?`<details><summary>来源与窗口</summary><p>${esc(t.source)}<br>实际 ${esc(t.firstDate)} — ${esc(t.asOf)}${t.requestedStart?`<br>请求 ${esc(t.requestedStart)} — ${esc(t.requestedEnd)}`:''}</p></details>`:''}</td><td>${num(t?.close)} / ${num(t?.ma20)}</td><td>${num(t?.rsi14)}</td><td>${num(t?.macd)} / ${num(t?.signal)} / ${num(t?.hist)}</td><td>${t?.asOf||'—'}<small>${esc(t?.adjustment||'')} · ${esc(t?.currency||'')}</small></td><td>${action('获取日线','company-live-prices',`data-company="${c.id}"`,'button small')}${action('导入 CSV','company-prices',`data-company="${c.id}"`,'button small')}</td></tr>`;}).join('')}</tbody></table></div><p class="muted">${comparable(cs,'technical')?'已录入技术数据的截止日、复权方式与币种一致。':'技术数据不完整或截止日 / 复权方式 / 币种不一致。'} 样本不足的指标显示“—”；MACD Hist = MACD − Signal，未乘 2。</p>`}`;}
function comparable(cs,type){if(cs.length<2||cs.some(c=>!c[type]))return false;let fields=type==='valuation'?['date','period','currency']:['asOf','adjustment','currency'];return fields.every(k=>cs.every(c=>c[type][k]===cs[0][type][k]));}
function settings(){return heading('CONNECTIONS & DATA','数据与设置','看清哪些已经连接，哪些仍需要配置。材料和研究记录保存在当前浏览器。')+`<div class="grid"><div><section class="card"><div class="card-head"><h2>公开数据与新闻</h2>${action(busy?'检查中…':'检查更新','refresh',busy?'disabled':'')}</div><p>${online?esc(remote.schedule):'当前显示随原型附带的公开数据快照。双击「启动原型.command」后使用 127.0.0.1:8765，可以检查更新。'}</p>${(remote.catalog||[]).map(c=>{let s=remote.sources[c.id];return `<div class="entry"><div class="card-head"><h3>${esc(c.name)}</h3><span class="pill ${s?.status==='ok'?'':'warm'}">${s?.status==='ok'?'已获取':s?.status==='stale'?'抓取失败 · 保留旧值':s?.status==='error'?'抓取失败':'等待首次检查'}</span></div><p>最近成功 ${stamp(s?.fetchedAt)}<br>最近检查 ${stamp(s?.checkedAt)}</p>${c.note?`<p>${esc(c.note)}</p>`:''}${s?.error?`<details><summary>查看错误</summary><p>${esc(s.error)}</p></details>`:''}<a href="${safeURL(c.url)}" target="_blank" rel="noopener noreferrer">原始来源 ↗</a>${c.kind==='feed'?`<label><input type="checkbox" data-feed="${c.id}" ${!state.disabledFeeds.includes(c.id)?'checked':''}>在我的信息面板显示此源</label>`:''}</div>`;}).join('')||empty('尚未读取数据源状态','离线页面展示带日期的采集快照，不会自动更新。')}<div class="notice">自动检查只在本地服务运行时工作。关闭电脑或服务后停止；再次启动会补查。未设置云端定时任务。</div></section><section class="card"><h2>尚未接通的范围</h2><ul class="list"><li>尚缺：GDP 分项、社融结构、金银完整供需、CFTC 持仓和交易所库存（现有年度摘要与两只 ETF 数据）</li><li>A 股自动财务：覆盖山东黄金、盛达资源、宁德时代、比亚迪、亿纬锂能五个样本；其他代码、实时行情与公告仍未接入；五个样本可主动获取历史日线</li><li>公众号与播客自动订阅：暂用材料主动导入</li><li>Open Notebook：底座 PoC 已验证，当前页面尚未接入其存储</li></ul></section></div><aside><section class="card"><h2>AI 辅助拆解</h2><span class="pill ${remote.ai?.configured?'':'warm'}">${remote.ai?.configured?'本地已配置 · 待实际调用验证':'等待本地配置'}</span><p style="margin-top:14px">${remote.ai?.configured?`${esc(remote.ai.host)} / ${esc(remote.ai.model)}`:'通过项目根目录 .env 配置兼容 Chat Completions 的接口。密钥只在本地服务端读取。'}</p>${action('查看配置说明','ai-help','','ghost')}<p>未配置时，可用关键词辅助归类与手动确认完成全部流程。模型分析不会自动覆盖已归档的判断。</p></section><section class="card"><h2>记录与备份</h2><p>${state.entries.length} 条观点 · ${state.watches.length} 个观察主题 · ${state.companies.length} 家公司</p><div class="actions">${action('导出全部记录','export')}${action('导入备份（合并）','restore')}</div><p class="muted">切换浏览器、端口或清除浏览器数据会影响本地记录。导出包含导入原文，请自行保管。</p>${state.legacy?`<p>检测到旧版研究记录，已保留原始数据。</p>${action('查看 / 转入旧记录','legacy','','ghost')}`:''}</section><section class="card"><h3>本版实际复用</h3><p>国内财经接口：AKShare 1.19.1<br>RSS 解析：feedparser<br>技术指标：TA-Lib<br>数据：FRED / 上金所 / 东方财富转录宏观数据<br>新闻：财联社 / 新浪 / 东方财富 / 官方 RSS</p><p>现成组件承担采集解析和计算；框架组织、证据归档与确认流程由本项目实现。</p></section></aside></div>`;}
function bindLinks(root){root.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));root.querySelectorAll('[data-node]:not([data-action])').forEach(b=>b.onclick=()=>{selected=b.dataset.node;render();});root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{subtab=b.dataset.tab;render();});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>dispatch(b.dataset.action,b.dataset));}
function collectDraft(){if($('#source-title'))Object.assign(draft,{title:$('#source-title').value.trim(),text:$('#source-text').value,kind:$('#source-kind').value,sourceURL:$('#source-url').value.trim()});if($('#claim'))Object.assign(draft,{claim:$('#claim').value.trim(),question:$('#question').value.trim(),counter:$('#counter').value.trim(),node:$('#target-node').value,stance:$('#stance').value,segment:Number($('#source-segment').value)});if(draft.aiQuote&&String(draft.mode).startsWith('AI 辅助')){if(draft.segment!==draft.aiSegment)draft.mode='AI 建议后改选段落 · 原引文不在当前段落，引用未校验';else if(draft.claim!==draft.aiClaim)draft.mode=draft.mode.replace('结论待核查','观点经人工改写，结论待核查');}if($('#keywords'))Object.assign(draft,{keywords:$('#keywords').value.trim(),watch:$('#track-topic').checked});if(!save())return;}
function bindPage(){if(route==='reader'){$('#page').oninput=e=>{if(e.target.id==='source-text'){draft.claim='';draft.question='';draft.counter='';draft.suggestions=null;draft.demo=false;draft.mode='手动整理';}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))collectDraft();};$('#page').onchange=e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))collectDraft();};if($('#source-file'))$('#source-file').onchange=async e=>{let f=e.target.files[0];if(!f)return;if(f.size>200000||!/\.(md|txt)$/i.test(f.name))return toast('请用不超过 200 KB 的 TXT / Markdown');try{let text=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());if(text.length>50000)throw Error('正文超过 50,000 字符，请选取一段完整材料');draft.claim='';draft.question='';draft.counter='';draft.suggestions=null;draft.demo=false;draft.mode='手动整理';draft.text=text;draft.title||=f.name.replace(/\.[^.]+$/,'');if(!save())return;render();}catch(err){toast(err.message);}};if($('#source-segment'))$('#source-segment').onchange=()=>{collectDraft();render();};if($('#ai-pick'))$('#ai-pick').onchange=e=>{collectDraft();applySuggestion(Number(e.target.value));render();};}$$('[data-feed]').forEach(x=>x.onchange=()=>{state.disabledFeeds=state.disabledFeeds.filter(f=>f!==x.dataset.feed);if(!x.checked)state.disabledFeeds.push(x.dataset.feed);if(!save())return;});}
async function dispatch(a,d={}){switch(a){case'company-financial':financialScope='mine';go('companies');subtab='financials';return render();case'research-detail':return researchDetail(d.entry);case'focus-edit':return editFocus();case'entry-check':return editCheck(d.entry,d.check);case'check-series':return checkSeries(d.entry,d.check);case'entry-watch':return watchFromEntry(d.entry);case'new-milestone':return addMilestone(d.watch);case'annual-import':return annualImport(d.node);case'filter-news':newsScope=$('#news-scope').value;newsSource=$('#news-source').value;newsQuery=$('#news-query').value.trim();return render();case'narrative-tab':narrativeTab=d.value;return render();case'template-detail':return templateDetail(d.template);case'use-template':return editWatch(null,d.template);case'milestone':return milestone(d.watch,Number(d.index));case'goto':return go(d.area);case'chain':route='metals';selected='gold';subtab='chain';location.hash='metals';return render();case'open-node':go(frame(d.node).area,d.node);return;case'node-framework':subtab='framework';selected=d.node;return render();case'node-data':if(route==='companies')subtab=d.node==='business'?'financials':'compare';else subtab='data';selected=d.node;return render();case'node-news':subtab='news';selected=d.node;return render();case'import-node':draft.node=frame(d.node)?d.node:'policy';readerStep=1;return go('reader');case'demo':return loadDemo();case'new-source':return newSource();case'news-import':return newsImport(d.news);case'reader-next':collectDraft();if(!draft.title||!draft.text.trim())return $('#reader-error').textContent='请填写材料标题和正文。';if(draft.sourceURL&&safeURL(draft.sourceURL)==='#')return $('#reader-error').textContent='链接需为 http:// 或 https:// 地址。';if(!draft.claim){const scores=FRAMES.map(f=>({id:f.id,score:f.tags.filter(t=>draft.text.toLowerCase().includes(t.toLowerCase())).length})).sort((a,b)=>b.score-a.score);if(scores[0].score)draft.node=scores[0].id;draft.mode='关键词辅助 · 待人工整理';draft.segment=Math.min(draft.segment,parts().length)||1;}readerStep=2;if(!save())return;return render();case'reader-back':collectDraft();readerStep=Math.max(1,readerStep-1);return render();case'reader-check':collectDraft();if(!draft.claim||!draft.question||!draft.counter)return $('#reader-error').textContent='请填写观点、验证问题和重新判断的条件。';readerStep=3;return render();case'reader-save':return archive();case'ai':return analyze();case'source':return showSource(d.entry);case'edit-entry':return editEntry(d.entry);case'entry-history':return entryHistory(d.entry);case'new-watch':return editWatch();case'edit-watch':return editWatch(d.watch);case'toggle-watch':{let w=state.watches.find(w=>w.id===d.watch);w.active=!w.active;log('切换观察状态',w.title);if(!save())return;return render();}case'watch-news':return watchNews(d.watch);case'add-company':return addCompany(d.role||'',d.entry);case'company-values':return companyValues(d.company);case'company-live-prices':return companyLivePrices(d.company);case'company-prices':return companyPrices(d.company);case'refresh':return refresh();case'export':return exportAll();case'restore':return restore();case'legacy':return legacy();case'ai-help':return dialog('本地配置 AI 接口',`<p>在项目根目录复制 .env.example 为 .env，填入服务商提供的 API 地址、密钥和模型名称，重启本地服务。</p><pre>LLM_BASE_URL=https://你的服务商/v1\nLLM_API_KEY=仅在本地填写\nLLM_MODEL=你的模型名称</pre><p>本版采用 Chat Completions 兼容协议；实际兼容性需要配置后测试。不要把密钥放进前端、导出文件或 GitHub。</p><p>AI 返回内容会检查节点是否存在、引用是否来自原段落；这不等于事实已被外部核验。</p>`);}}
function loadDemo(){if(draft.text.trim()&&!draft.demo){dialog('保留当前草稿', '<p>当前已有未归档的材料。请先归档或导出备份，再载入示例。</p>');return;}Object.assign(draft,{title:'政策议题如何改变投资假设 · 教学示例',kind:'教学示例',demo:true,text:'这是一份原创教学材料，不对应真实播客或已核实的政治事件。\n\n一位讨论者提出：某种新的政治诉求可能进入政策议程，进而改变税收、支出或产业规则。但他不能确定这一过程是否会发生。\n\n这条线索需要区分舆论关注、政策提案与实际执行；仅有热度不能证明政策会落地，也不能直接推出某类资产会受益。',claim:'讨论者提出新的政治诉求可能影响政策规则，但能否进入议程和执行仍不确定。',question:'是否出现正式政策提案、执行安排或实际支出变化？',counter:'议题未进入政策议程，或最终规则与讨论方向相反。',node:'policy',segment:2,stance:'提出新问题',keywords:'policy,财政,税收',watch:true,mode:'预置教学示例 · 未调用 AI',suggestions:null,sourceURL:''});readerStep=1;if(!save())return;go('reader');}
function archive(){collectDraft();if(draft.watch&&!draft.keywords)return $('#reader-error').textContent='开启追踪时，请至少填写一个关键词。';if(state.entries.some(e=>e.title===draft.title&&e.text===draft.text&&e.claim===draft.claim&&e.node===draft.node))return $('#reader-error').textContent='这条观点已经归档，可以修改观点或选择另一段继续整理。';const e={...draft,research:{timestamp:sourceTimestamp(draft),path:[],checks:[]},id:uid(),version:1,created:now(),history:[{time:now(),type:'确认归档',note:'用户确认观点、来源段落与框架位置'}]};delete e.suggestions;delete e.aiIndex;if(e.segment!==e.aiSegment){delete e.aiQuote;}delete e.aiSegment;delete e.aiClaim;state.entries.push(e);if(draft.watch)state.watches.push({id:uid(),entryId:e.id,title:e.claim,question:e.question,counter:e.counter,node:e.node,keywords:e.keywords,active:true,seen:[],demo:e.demo,created:now()});log('归档观点',e.title);if(!persist(()=>{state.entries=state.entries.filter(x=>x.id!==e.id);state.watches=state.watches.filter(w=>w.entryId!==e.id);state.history.shift();})){$('#reader-error').textContent='未能保存到浏览器（存储已满或不可用），这条观点没有归档；请先导出备份。';return;}dialog('已归档，研究有了一个落点',`<div class="notice">${esc(AREAS[frame(e.node).area])} → ${esc(frame(e.node).name)} → 我的证据</div><p>原文 §${e.segment}（${esc(e.research?.timestamp||'未标时间戳')}）、观点和验证条件都已保存。${e.watch?'同时建立了持续观察主题。':''}</p>`,`<button class="primary" id="view-archived">查看框架中的证据 →</button><button class="button" id="another">继续整理同一材料</button>`);$('#view-archived').onclick=()=>{closeDialog();go(frame(e.node).area,e.node);subtab='evidence';render();};$('#another').onclick=()=>{closeDialog();Object.assign(draft,{claim:'',question:'',counter:'',watch:false});readerStep=2;if(!save())return;go('reader');};}
function showSource(entryId){let e=state.entries.find(e=>e.id===entryId);dialog(e.title,`<p>${esc(e.kind)} · ${esc(e.research?.timestamp||'未标时间戳')} · ${e.sourceURL?`<a href="${safeURL(e.sourceURL)}" target="_blank" rel="noopener noreferrer">原始链接 ↗</a>`:'用户导入的本地文字'} · 高亮为引用段落</p>${e.text.split(/\n\s*\n/).filter(x=>x.trim()).map((p,i)=>`<div id="seg-${i+1}" class="source-line ${i+1===e.segment?'selected':''}"><b>§${i+1}</b><span>${esc(p.trim())}</span></div>`).join('')}`);$('#seg-'+e.segment)?.scrollIntoView({block:'center'});}
function editEntry(entryId){const e=state.entries.find(x=>x.id===entryId),base=e.version;dialog('修订研究判断',`<p>当前 v${base}。先说明新依据，再查看前后变化。原文引用保持为最初依据；新的证据可另行导入。</p><label for="edit-claim">修改后的观点</label><textarea id="edit-claim" maxlength="2000">${esc(e.claim)}</textarea><label for="edit-reason">本次修改理由 / 新依据说明</label><textarea id="edit-reason" maxlength="1500"></textarea><label for="edit-stance">证据作用</label><select id="edit-stance">${['待核查','补充背景','支持假设','挑战假设','提出新问题'].map(x=>`<option ${x===e.stance?'selected':''}>${x}</option>`).join('')}</select><div class="error" id="edit-error"></div>`,`<button class="primary" id="review-change">对比变更</button>`);$('#review-change').onclick=()=>{let after=$('#edit-claim').value.trim(),reason=$('#edit-reason').value.trim(),stance=$('#edit-stance').value;if(!after||!reason)return $('#edit-error').textContent='请填写观点与修改理由。';if(after===e.claim&&stance===e.stance)return $('#edit-error').textContent='没有变化，无需修订。';dialog('确认修改后才更新',`<h3>修改前 · v${base}</h3><p>${esc(e.claim)} · ${esc(e.stance)}</p><h3>修改后 · v${base+1}</h3><p>${esc(after)} · ${esc(stance)}</p><h3>依据说明</h3><p>${esc(reason)}</p>`,`<button class="primary" id="accept-change">确认更新</button>`);$('#accept-change').onclick=()=>{if(e.version!==base)return toast('版本已变化，请重新打开修订');e.history.push({time:now(),type:'修订判断',before:e.claim,after,beforeStance:e.stance,afterStance:stance,note:reason,version:base+1});const prev=[e.claim,e.stance];e.claim=after;e.stance=stance;e.version++;if(!persist(()=>{[e.claim,e.stance]=prev;e.version--;e.history.pop();}))return;closeDialog();render();toast('已保存新版本；关联观察主题保留原假设，可单独修订');};};}
function entryHistory(id){let e=state.entries.find(x=>x.id===id);dialog('观点修订记录',e.history.map(h=>`<div class="entry"><h3>${esc(h.type)}</h3><small>${stamp(h.time)}</small><p>${esc(h.note)}</p>${h.before?`<p>修改前：${esc(h.before)}</p><p>修改后：${esc(h.after)}</p>`:''}</div>`).join(''));}
function editWatch(id,templateId){let t=NARRATIVE_TEMPLATES.find(t=>t.id===templateId);let w=state.watches.find(x=>x.id===id)||(t?{title:t.claim,node:t.node,question:t.question,counter:t.counter,keywords:t.keywords,baseline:t.baseline}:{title:'',node:'policy',question:'',counter:'',keywords:'',baseline:''});dialog(id?'编辑观察主题':t?'从方法模板建立个人观察':'建立观察主题',`${t?`<div class="notice">模板只提供起点，请修改为自己的假设。${esc(t.source)}</div>`:''}<label for="watch-title">主题 / 待验证假设</label><input id="watch-title" maxlength="300" value="${esc(w.title)}"><label for="watch-node">关联框架</label><select id="watch-node">${selectNodes(w.node)}</select><label for="watch-question">验证什么</label><textarea id="watch-question" maxlength="1200">${esc(w.question)}</textarea><label for="watch-counter">什么情况会推翻判断</label><textarea id="watch-counter" maxlength="1200">${esc(w.counter)}</textarea><label for="watch-baseline">预期基准：谁、何时、什么指标与期间</label><textarea id="watch-baseline" maxlength="1500">${esc(w.baseline||'')}</textarea><label for="watch-keywords">标题关键词（逗号分隔）</label><input id="watch-keywords" maxlength="250" value="${esc(w.keywords)}"><p>匹配当前已接入的信息源，不进行全网检索。</p><div class="error" id="watch-error"></div>`,`<button class="primary" id="save-watch">保存观察主题</button>`);$('#save-watch').onclick=()=>{let v={title:$('#watch-title').value.trim(),node:$('#watch-node').value,question:$('#watch-question').value.trim(),counter:$('#watch-counter').value.trim(),keywords:$('#watch-keywords').value.trim(),baseline:$('#watch-baseline').value.trim()};if(['title','node','question','counter','keywords'].some(k=>!v[k]))return $('#watch-error').textContent='请填写主题、验证问题、反证条件与关键词。';if(id){log('修订观察主题',JSON.stringify({before:w,after:v}));Object.assign(w,v);}else state.watches.push({...v,id:uid(),active:true,seen:[],created:now(),...(t?{templateId:t.id,templateSource:t.source,milestones:t.milestones.map(title=>({title,status:'待核查',history:[]}))}:{})});narrativeTab='watches';if(!save())return;closeDialog();render();};}
function watchNews(id){let w=state.watches.find(x=>x.id===id),items=matched(w);dialog('主题匹配信息',`<p>${esc(w.title)}</p><p>关键词：${esc(w.keywords)} · ${w.active?'观察中':'已暂停，以下为已有缓存匹配'}</p>${newsItems(items)}`,items.length?'<button class="button" id="mark-read">将这些条目标为已读</button>':'');if($('#mark-read'))$('#mark-read').onclick=()=>{w.seen=[...new Set([...(w.seen||[]),...items.map(x=>x.id)])];if(!save())return;closeDialog();render();};}
function addCompany(role,originEntryId){dialog('添加 A 股研究对象',`<p>先记录名称、代码和业务位置。当前未连接证券主数据，请自行核对。</p><div class="form-row"><div><label for="company-name">公司名称</label><input id="company-name" maxlength="80"></div><div><label for="company-code">6 位 A 股代码</label><input id="company-code" inputmode="numeric" maxlength="6"></div></div><label for="company-role">业务 / 产业链位置</label><input id="company-role" value="${esc(role)}" maxlength="100" placeholder="例如：金矿开采 / 冶炼 / 珠宝零售"><label for="company-reason">为什么值得研究，待核实什么</label><textarea id="company-reason" maxlength="1000"></textarea><div id="company-error" class="error"></div>`,`<button class="primary" id="save-company">添加公司</button>`);$('#save-company').onclick=()=>{let name=$('#company-name').value.trim(),code=$('#company-code').value.trim(),role=$('#company-role').value.trim(),reason=$('#company-reason').value.trim();if(!name||!/^\d{6}$/.test(code)||!role||!reason)return $('#company-error').textContent='请填写名称、6 位代码、业务位置和研究理由。';if(state.companies.some(c=>c.code===code))return $('#company-error').textContent='这家公司已在列表中。';state.companies.push({id:uid(),name,code,role,reason,created:now(),history:[],originEntryIds:originEntryId?[originEntryId]:[]});if(!save())return;closeDialog();go('companies');subtab='list';render();};}
function companyValues(id){let c=state.companies.find(x=>x.id===id),v=c.valuation||{};dialog(`${c.name} · 估值快照`,`<p>手动记录来源披露的倍数，不根据缺失字段倒算。保留日期与报告期以检查横向可比性。</p><div class="form-row"><div><label for="pe">PE(TTM)，可留空</label><input id="pe" type="number" step="any" value="${v.pe??''}"></div><div><label for="pb">PB，可留空</label><input id="pb" type="number" step="any" value="${v.pb??''}"></div></div><div class="form-row"><div><label for="v-date">估值对应日期</label><input id="v-date" type="date" value="${esc(v.date||'')}"></div><div><label for="v-period">财报截止期</label><input id="v-period" type="date" value="${esc(v.period||'')}"></div></div><label for="v-currency">币种</label><select id="v-currency"><option>CNY</option></select><label for="v-source">来源与口径说明</label><textarea id="v-source" maxlength="1000">${esc(v.source||'')}</textarea><div id="v-error" class="error"></div>`,`<button class="primary" id="save-values">保存快照</button>`);$('#save-values').onclick=()=>{const parse=id=>$(id).value===''?null:Number($(id).value);let n={pe:parse('#pe'),pb:parse('#pb'),date:$('#v-date').value,period:$('#v-period').value,currency:$('#v-currency').value,source:$('#v-source').value.trim()};if((n.pe===null&&n.pb===null)||!n.date||!n.period||!n.source||[n.pe,n.pb].some(x=>x!==null&&!Number.isFinite(x))||n.period>n.date||n.date>now().slice(0,10))return $('#v-error').textContent='请填写至少一个有效倍数、合法日期与来源；报告期不能晚于估值日期。';c.history.push({time:now(),type:'估值快照',before:c.valuation||null,after:n});const prevValuation=c.valuation;c.valuation=n;if(!persist(()=>{c.valuation=prevValuation;c.history.pop();}))return;closeDialog();subtab='compare';render();};}
function companyPrices(id){const c=state.companies.find(x=>x.id===id);dialog(`${c.name} · 导入历史价格`,`<p>上传 CSV，必须包含 <code>date,close</code> 两列，日期 YYYY-MM-DD。按日期排序后计算；重复日期、非正价格会被拒绝。MACD 至少需要 34 个有效值。</p><label for="price-file">价格文件（最多 500 KB）</label><input id="price-file" type="file" accept=".csv,text/csv"><div class="form-row"><div><label for="adjustment">价格口径</label><select id="adjustment"><option>前复权</option><option>后复权</option><option>不复权</option></select></div><div><label for="price-currency">币种</label><select id="price-currency"><option>CNY</option></select></div></div><label for="price-source">价格来源及下载日期</label><input id="price-source" maxlength="200"><p>${online?'计算由本地 TA-Lib 完成，文件不发送给模型。':'需要先启动本地服务才能计算。'}</p><div class="error" id="price-error"></div>`,`<button class="primary" id="calculate" ${online?'':'disabled'}>导入并计算</button>`);$('#calculate').onclick=async()=>{const file=$('#price-file').files[0],source=$('#price-source').value.trim(),adjustment=$('#adjustment').value,currency=$('#price-currency').value;if(!file||file.size>500000||!source)return $('#price-error').textContent='请选择有效 CSV，并填写来源。';let btn=$('#calculate');btn.disabled=true;try{let csv=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());let result=await api('/api/technical',{csv});c.history.push({time:now(),type:'导入价格',before:c.technical||null});const prevTechnical=c.technical;c.technical={...result,source,adjustment,currency};if(!persist(()=>{c.technical=prevTechnical;c.history.pop();})){btn.disabled=false;return;}closeDialog();subtab='compare';render();toast('已用 TA-Lib 计算；样本不足的指标留空');}catch(e){$('#price-error').textContent=e.message;btn.disabled=false;}};}
async function api(path,payload){const r=await fetch(path,{method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json'}:{},body:payload?JSON.stringify(payload):undefined,signal:AbortSignal.timeout(path==='/api/analyze'?95000:45000)});let v;try{v=await r.json();}catch{throw Error('本地服务未连接或返回异常，请通过启动脚本打开');}if(!r.ok)throw Error(v.error||'请求失败');return v;}
async function loadRemote(){if(location.protocol==='file:')return;try{const live=await api('/api/state');online=true;const hasLive=Object.keys(live.sources||{}).length>0;if(hasLive||typeof PUBLIC_SNAPSHOT==='undefined')remote=live;else remote={...PUBLIC_SNAPSHOT,ai:live.ai||{configured:false},refreshing:live.refreshing,emptyLive:true};}catch{online=false;}const typing=$('#page').contains(document.activeElement)&&['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName);if(!$('#dialog').open&&!typing)render();else $('#connection').textContent=online?'本地数据服务已连接':'离线模式';}
async function refresh(){if(!online)return toast('请先双击启动原型.command 开启本地数据服务');if(busy)return;busy=true;render();try{await api('/api/refresh',{});let finished=false;for(let i=0;i<90;i++){await new Promise(r=>setTimeout(r,1500));remote=await api('/api/state');if(!remote.refreshing){finished=true;break;}}if(!finished)throw Error('后台仍在检查，请稍后查看连接状态');online=true;toast('检查完成；失败来源保留旧缓存，请看连接状态');}catch(e){toast(e.message);}finally{busy=false;render();}}
function applySuggestion(i){let s=draft.suggestions[i];Object.assign(draft,{claim:s.claim,node:s.node,segment:s.segment,question:s.question,counter:s.counter,keywords:s.keywords,aiQuote:s.quote,aiSegment:s.segment,aiClaim:s.claim,mode:`AI 辅助 · ${remote.ai.model} · 引用位置已校验，结论待核查`,aiIndex:i,stance:'待核查'});if(!save())return;}
async function analyze(){collectDraft();if(busy)return;const sourceText=draft.text,sourceTitle=draft.title,fields=()=>JSON.stringify([draft.claim,draft.question,draft.counter,draft.node,draft.segment]),before=fields();busy=true;render();try{const result=await api('/api/analyze',{text:sourceText});if(draft.text!==sourceText||draft.title!==sourceTitle)throw Error('分析期间材料已更改，旧结果未应用；请重新分析当前材料');draft.suggestions=result.suggestions;if(fields()!==before){draft.aiIndex=null;if(!save())return;toast('已生成待审建议；你在等待期间修改了内容，未自动覆盖，可在“本次 AI 提出的观点”中选择');}else{applySuggestion(0);toast('已生成待审建议；请核对引用、观点和归类');}}catch(e){toast(e.message);}finally{busy=false;render();}}
function exportAll(){let payload={...state,draft,exportedAt:now()};download('观澜-全部研究记录-'+now().slice(0,10)+'.json',JSON.stringify(payload,null,2));}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function restore(){dialog('合并导入备份','<p>只接受本版导出的 schema=2 备份；相同 ID 保留当前版本，不覆盖已有记录。草稿不合并。</p><input type="file" id="backup-file" accept=".json"><div class="error" id="restore-error"></div>','<button class="primary" id="restore-confirm">检查并合并</button>');$('#restore-confirm').onclick=async()=>{try{let f=$('#backup-file').files[0];if(!f||f.size>5_000_000)throw Error('请选择小于 5 MB 的 JSON 文件');let v=JSON.parse(await f.text());validateBackup(v);if(typeof v.focusKeywords==='string'&&!state.focusKeywords)state.focusKeywords=v.focusKeywords;let count=0;const added=[];for(let k of ['entries','watches','companies'])for(let x of v[k])if(!state[k].some(y=>y.id===x.id)){state[k].push(x);added.push([k,x.id]);count++;}log('合并备份',`${count} 条新记录`);if(persist(()=>{for(const [k,id] of added)state[k]=state[k].filter(y=>y.id!==id);state.history.shift();})){closeDialog();render();toast(`已合并 ${count} 条记录，同 ID 原记录保留`);}else $('#restore-error').textContent='浏览器存储空间不足，备份未合并；原有记录未改变。'}catch(e){$('#restore-error').textContent=e.message;}};}
function validateBackup(v){if(!v||v.schema!==2)throw Error('备份版本不匹配');const str=x=>typeof x==='string';for(let k of ['entries','watches','companies']){if(!Array.isArray(v[k])||v[k].length>3000)throw Error('备份结构不正确');for(let x of v[k]){if(!x||typeof x!=='object')throw Error('记录格式错误');if(x.history&&(!Array.isArray(x.history)||x.history.some(h=>!h||typeof h!=='object')))throw Error('历史记录格式错误');if(!str(x.id)||!x.id||x.id.length>100||!/^[\w-]+$/.test(x.id))throw Error('记录 ID 不合法');validateResearchExtras(k,x);if(k==='entries'&&(!['title','text','claim','question','counter','mode','stance'].every(f=>str(x[f]))||!frame(x.node)||!Array.isArray(x.history)||!Number.isInteger(x.version)||x.version<1||!Number.isInteger(x.segment)||x.segment<1||x.segment>x.text.split(/\n\s*\n/).filter(s=>s.trim()).length))throw Error('证据记录不完整');if(k==='watches'){if(!['title','question','counter','keywords'].every(f=>str(x[f]))||!frame(x.node)||!Array.isArray(x.seen)||typeof x.active!=='boolean')throw Error('观察主题不完整');if(x.milestones&&(!Array.isArray(x.milestones)||x.milestones.some(m=>!m||!str(m.title)||!str(m.status)||!Array.isArray(m.history)||m.history.some(h=>!h||typeof h!=='object'))))throw Error('里程碑格式错误');}if(k==='companies'){if(!['name','code','role','reason'].every(f=>str(x[f]))||!/^\d{6}$/.test(x.code)||!Array.isArray(x.history))throw Error('公司记录不完整');if(x.valuation){const z=x.valuation;if(!['date','period','currency','source'].every(f=>str(z[f]))||!/^\d{4}-\d{2}-\d{2}$/.test(z.date)||!/^\d{4}-\d{2}-\d{2}$/.test(z.period)||['pe','pb'].some(f=>z[f]!==null&&!Number.isFinite(z[f])))throw Error('估值快照格式错误');}if(x.technical){const z=x.technical;if(!['asOf','firstDate','source','adjustment','currency'].every(f=>str(z[f]))||!/^\d{4}-\d{2}-\d{2}$/.test(z.asOf)||!/^\d{4}-\d{2}-\d{2}$/.test(z.firstDate)||!Number.isInteger(z.rows)||['close','ma20','rsi14','macd','signal','hist'].some(f=>z[f]!==null&&!Number.isFinite(z[f])))throw Error('价格计算结果格式错误');}}}}}
function legacy(){const records=state.legacy?.records||[];dialog('旧版材料保留区',`<p>原有 localStorage 未删除。选择一条记录，将第一份原文复制到新版研读草稿；旧记录与历史仍留在备份中。</p>${records.map((r,i)=>`<div class="entry"><h3>${esc(r.title)}</h3><p>${esc(r.claim)}</p><button class="button" data-legacy-index="${i}">复制到材料研读</button></div>`).join('')}`);$$('[data-legacy-index]').forEach(b=>b.onclick=()=>{if(draft.text.trim()&&!draft.demo)return toast('当前已有草稿，请先归档或导出后再转入旧记录');let r=records[Number(b.dataset.legacyIndex)];if(!r.sources?.[0])return toast('该记录无可用原文');Object.assign(draft,{title:r.title,text:r.sources[0].text,kind:'研究记录',claim:r.claim||'',question:(r.questions||[]).join('；'),counter:r.conditions||'',segment:1,node:'policy',demo:!!r.demo,mode:'旧版记录复制 · 归类待确认',sourceURL:'',watch:false,keywords:'',suggestions:null});readerStep=1;if(!save())return;closeDialog();go('reader');});}
$('#export').onclick=exportAll;
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==route){route=AREAS[next]?next:'home';subtab='framework';render();}});
route=AREAS[location.hash.slice(1)]?location.hash.slice(1):'home';render();if(!storageProblem)save();loadRemote();
setInterval(()=>{if(!busy&&!document.hidden)loadRemote();},60000);

function blankDraft(){return {title:'',text:'',kind:'播客笔记',sourceURL:'',claim:'',question:'',counter:'',node:'policy',segment:1,stance:'待核查',keywords:'',watch:false,mode:'手动整理',demo:false};}
function newSource(){const start=()=>{draft=blankDraft();readerStep=1;if(!save())return;closeDialog();go('reader');};if(draft.text.trim()&&!state.entries.some(e=>e.text===draft.text&&e.claim===draft.claim)){dialog('开始一份新材料','<p>当前研读草稿会被清空，已归档记录会保留。可以先导出备份保留草稿。</p>','<button class="primary" id="clear-draft">清空草稿并开始</button>');$('#clear-draft').onclick=start;}else start();}
function newsImport(id){let item=allNews().find(i=>i.id===id);if(!item)return;if(draft.text.trim()&&!state.entries.some(e=>e.text===draft.text&&e.claim===draft.claim))return toast('研读区已有草稿，请先归档，或在材料研读中新建材料');draft={...blankDraft(),title:item.title,sourceURL:item.url,kind:'文章',node:item.nodes[0]||'policy'};readerStep=1;if(!save())return;closeDialog();go('reader');toast('已带入标题和原文链接，请阅读原文后补充正文');}

function metricCoverage(node,index){if(node==='silver'&&index===0)return '部分年度摘要 · 非自动序列';if(node==='gold'&&index===1)return '单只 ETF + 年度净需求摘要';if(node==='gold'&&index===2)return '部分年度供给摘要 · AISC 未接入';const mapping={growth:[[],['cn_pmi'],[]],financial:[[],['DFII10'],['DTWEXBGS']],inflation:[['cn_cpi','cn_ppi'],[],['T10YIE']],gold:[['DFII10','DTWEXBGS'],[],[]]};const ids=mapping[node]?.[index]||[];if(!ids.length)return '未接入';const n=ids.filter(id=>remote.sources[id]?.status==='ok').length;const partial=(node==='growth'&&index===1)||(node==='inflation'&&index===0);return n===ids.length?(partial?'部分指标已获取':'公开来源已获取'):n?'部分已获取':'待获取 / 查看连接状态';}

function templateDetail(id){const t=NARRATIVE_TEMPLATES.find(t=>t.id===id);dialog(t.title,`<p>${esc(t.question)}</p><div class="notice"><b>先固定预期基准</b><br>${esc(t.baseline)}</div><div class="branch-grid">${t.branches.map(([name,condition,evidence])=>`<section><h3>${esc(name)}</h3><p>${esc(condition)}</p><small>${esc(evidence)}</small></section>`).join('')}</div><h3>需要重新判断的条件</h3><p>${esc(t.counter)}</p><p class="basis">${esc(t.source)}</p>`,action('用它建立观察 →','use-template',`data-template="${t.id}"`,'primary'));}
function milestone(id,index){const w=state.watches.find(w=>w.id===id),m=w?.milestones?.[index];if(!m)return;dialog(m.title,`<p>状态是你对证据的判断，不会自动决定整体假设是否成立。</p>${m.rule?`<div class="notice">初始判定规则：${esc(m.rule)}</div>`:''}<label for="m-status">当前状态</label><select id="m-status">${['待核查','出现支持线索','出现反证','延期'].map(s=>`<option ${s===m.status?'selected':''}>${s}</option>`).join('')}</select><label for="m-due">下次人工复核日</label><input id="m-due" type="date" value="${esc(m.dueDate||'')}"><p>延期必须选择晚于今天的日期；待核查或延期事项到日后再次提示，不自动改变判断。</p><label for="m-evidence">依据、来源与信息日期</label><textarea id="m-evidence" maxlength="1800" placeholder="写出观察到的证据、来源链接或材料段落，以及信息对应的时间。">${esc(m.note||'')}</textarea><div id="m-error" class="error"></div><details><summary>已记录的状态变化（${m.history.length}）</summary>${m.history.map(h=>`<p>${stamp(h.time)} · ${esc(h.status)}<br>${esc(h.note)}</p>`).join('')||'<p>暂无记录</p>'}</details>`,`<button class="primary" id="m-save">确认记录</button>`);$('#m-save').onclick=()=>{const status=$('#m-status').value,note=$('#m-evidence').value.trim(),dueDate=$('#m-due').value;if(!note)return $('#m-error').textContent='请填写依据和来源，避免只改变结论标签。';if((dueDate&&!validResearchDate(dueDate))||(['待核查','延期'].includes(status)&&!dueDate))return $('#m-error').textContent='请填写有效的下次复核日';if(status==='延期'&&dueDate<=localDay())return $('#m-error').textContent='延期日期必须晚于今天';m.history.push({time:now(),status,note,previous:m.status,previousDueDate:m.dueDate||'',dueDate});m.status=status;m.note=note;m.dueDate=dueDate;if(!save())return;closeDialog();render();};}


document.addEventListener('change',e=>{if(e.target.id==='financial-scope'){financialScope=e.target.value;financialPeriod='';render();}});
